import os
import awsbedrock

def normalize_expense(payload, config=None):
    config = config or {}
    document_id = awsbedrock.start_document_text_detection(job_name="expense_extraction",
        document={"bytes": payload},
        output_config={"s3_bucket_name": config["s3_bucket"], "s3_key_prefix": config["s3_folder"]})['jobId']
    while True:
        status = awsbedrock.get_document_text_detection(job_id=document_id)['status']
        if status == "SUCCEEDED":
            break
    text = awsbedrock.get_document_text_detection(job_id=document_id)['blocks'][0]['text']

    result = {
        "amount": None,
        "currency": None,
        "date": None,
        "vendor": None,
        "total_amount": None,
        "items": []
    }

    lines = text.splitlines()
    for line in lines:
        if "TOTAL" in line.upper():
            result["total_amount"] = float(line.split()[-1])
        elif ":" in line.upper():
            key, value = line.split(":", 1)
            key = key.strip().upper()
            value = value.strip()
            if key == "DATE":
                result["date"] = value
            elif key == "VENDOR":
                result["vendor"] = value
            elif key == "AMOUNT":
                amount, currency = parse_amount_value(value)
                result["amount"] = amount
                result["currency"] = currency
        else:
            # Extract line items
            parts = line.split("\t")
            if len(parts) >= 3:
                qty, desc, unit_price = parts[:3]
                result["items"].append({
                    "quantity": int(qty),
                    "description": desc,
                    "unit_price": float(unit_price.replace(",", "")) if unit_price else None
                })

    return result

def parse_amount_value(value):
    parts = value.replace(",", "").split()
    if len(parts) >= 2 and parts[-1].upper() in ["USD", "EUR", "GBP"]:
        return float(parts[0]), parts[-1].upper()
    return float(value), "USD"
